import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.CAKCj7G0.js";const m=JSON.parse('{"title":"组件状态","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/2-5.组件状态.md","filePath":"DuOneClass/09.react/2-5.组件状态.md"}'),o={name:"DuOneClass/09.react/2-5.组件状态.md"};function p(n,t,_,l,i,c){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="组件状态" tabindex="-1">组件状态 <a class="header-anchor" href="#组件状态" aria-label="Permalink to &quot;组件状态&quot;">​</a></h1><p>组件状态：组件可以自行维护的数据</p><p>组件状态仅在类组件中有效</p><p>状态（state），本质上是类组件的一个属性，是一个对象</p><p><strong>状态初始化</strong></p><p><strong>状态的变化</strong></p><p>不能直接改变状态：因为React无法监控到状态发生了变化</p><p>必须使用this.setState({})改变状态</p><p>一旦调用了this.setState，会导致当前组件重新渲染</p><p><strong>组件中的数据</strong></p><ol><li>props：该数据是由组件的使用者传递的数据，所有权不属于组件自身，因此组件无法改变该数组</li><li>state：该数组是由组件自身创建的，所有权属于组件自身，因此组件有权改变该数据</li></ol>',11)])])}const u=e(o,[["render",p]]);export{m as __pageData,u as default};
